#!/usr/bin/env python3
"""Inspect report_unpacked/word/document.xml: list paragraphs, their styles, and text."""
import sys
from xml.dom import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local(tag):
    return tag.split("}")[-1] if "}" in tag else tag

dom = minidom.parse("report_unpacked/word/document.xml")

for i, p in enumerate(dom.getElementsByTagNameNS(W, "p")):
    style = None
    for pPr in p.getElementsByTagNameNS(W, "pPr"):
        for child in pPr.childNodes:
            if child.nodeType == child.ELEMENT_NODE and local(child.tagName) == "pStyle":
                style = child.getAttributeNS(W, "val")
    text = "".join(
        t.data
        for r in p.getElementsByTagNameNS(W, "r")
        for t in r.getElementsByTagNameNS(W, "t")
    )
    print(f"[{i}] style={style!r} text={text!r}")

