"""Show raw XML of paragraphs matching candidate headline text in document.xml."""
import sys
from xml.dom import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local(tag):
    return tag.split("}")[-1] if "}" in tag else tag

def text_of_t(t):
    return "".join(n.data for n in t.childNodes if n.nodeType == n.TEXT_NODE)

doc_path = sys.argv[1]
dom = minidom.parse(doc_path)

for i, p in enumerate(dom.getElementsByTagNameNS(W, "p")):
    text = "".join(
        text_of_t(t)
        for r in p.getElementsByTagNameNS(W, "r")
        for t in r.getElementsByTagNameNS(W, "t")
    )
    if text and text == text.upper() and len(text.strip()) > 3:
        print(f"=== paragraph index {i}, text={text!r} ===")
        print(p.toprettyxml(indent="  ")[:2000])
        print()

